			function fn_callCommCd() {
			    
			    if(ValueUtil.isNull(untTaskwk)) {
			        untTaskwk = untTaskwkSeCd;
			    }
			        
			    for(var i=0; i<app.lookup("dsCommParam").getRowCount(); i++) {
			        var sCmmnsId = app.lookup("dsCommParam").getValue(i, "CMMNS_ID");
			        if(sCmmnsId == "SRVC_TYPE_SE_CD") {
			//            console.log("sCmmnsId : " + sCmmnsId);
			            app.lookup("dsCommParam").setValue(i, "UNIT_CODE", untTaskwk)
			        }

			        if(sCmmnsId == "SRVC_TYPE_SE_CD") {
			//            console.log("UNIT_CODE : " + app.lookup("dsCommParam").getValue(i, "UNIT_CODE"));
			        }
			    }

			    /*공통 서비스 호출 (공통코드)*/
			    util.Submit.send(app, "subOnLoad", function(pbSuccess) {
			        if (pbSuccess) {

			            // 목록화면에서 상세에 setDtlInfo 함수실행요청시 subOnload 서브미션의
			            // done 여부를 알수 없기 때문에 redraw 적용
			            util.Control.redraw(app, "grpData");
			        }
			    });
			}

