			/*
			 * 탭 폴더에서 selection-change 이벤트 발생 시 호출.
			 * Tab Item을 선택한 후에 발생하는 이벤트.
			 */
			function onTabPgmSelectionChange(e) {
			    var vnSeltTabId = util.Tab.getSelectedId(app, "tabPgm");
			    var submission = null;
			    app.lookup("dmSearch").clear(); // 조회조건
			    app.lookup("dmSearch").setValue("RESRCE_NO", util.DataSet.getValue(app, "dsDetail", 0, "RESRCE_NO"));

			    if (msCrudType != "CREATE") {
			        //프로그램
			        if (vnSeltTabId == "1") {
			            app.lookup("dsProgrmList").clear(); // 프로그램목록
			            submission = "subResrceProgrm";

			        } //담당자
			        else if (vnSeltTabId == "2") {
			            util.DataSet.clear(app, "dsPicList");
			            submission = "subResrcePic";

			        } //변경이력
			        else if (vnSeltTabId == "3") {
			            util.DataSet.clear(app, "dsChgHstrList");
			            submission = "subResrceChgHstr";

			        }
			        //조회 서브미션 호출
			        util.Submit.send(app, submission, function(pbSuccess) {

			            if (pbSuccess) {
			                if (vnSeltTabId == "1") {
			                    app.lookup("dsSchdlList").clear(); // 강의목록

			                    var nRowCnt = util.Grid.getRowCount(app, "grdProgMainList");

			                    if (nRowCnt > 0) {
			                         util.Grid.selectRow(app, "grdProgMainList", 0, false);
			                        app.lookup("dsInstrList").clear(); // 강사목록
			                        app.lookup("dmSearch").setValue("PROGRM_NO", app.lookup("dsProgrmList").getValue(0, "PROGRM_NO"));

			                        util.Submit.send(app, "subResrceProgrmSchdl", function(pbSuccess) {
			                            if (pbSuccess) {
			                                
			                                var nDtlRowCnt = util.Grid.getRowCount(app, "grdProgDtlList");

			                                if (nDtlRowCnt > 0) {
			                                    util.Grid.selectRow(app, "grdProgDtlList", 0, false);
			                                    app.lookup("dmSearch").setValue("LCTRE_SN", app.lookup("dsSchdlList").getValue(0, "LCTRE_SN"));

			                                    util.Submit.send(app, "subResrceProgrmInstr", function(pbSuccess) {});
			                                }
			                            }
			                        });
			                    }
			                }
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			            util.Control.redraw(app, "tabPgm");
			        });
			    }
			}

