			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb_PIC_NMClick(e){
			    var sipb_PIC_NM = e.control;
			    
			        //종사자(담당자)검색
			    util.Dialog.open(app, "app/itgcms/syscmmn/popup/WorkerSingle", "종사자검색", 1200, 670, function(e) {

			        var dialog = e.control;
			        var instrIdx = app.lookup("grdList").getSelectedRowIndex();
			        var voReturnVal = dialog.returnValue;

			        if (!ValueUtil.isNull(voReturnVal)) {
			            var dsPicList = app.lookup("dsPicList");
			//                console.log("MEMBER_NO:::::" + voReturnVal.getValue("MEMBER_NO"));
			            for (var i = 0; i < dsPicList.getRowCount(); i++) {
			                var picNo = dsPicList.getValue(i, "PIC_NO");
			//                console.log("PIC_NO:::::" + picNo);

			                if (picNo == voReturnVal.getValue("MEMBER_NO")) {
			                    util.Msg.alert(app, "해당 담당자가 존재합니다.\n다시 선택해 주십시오.");
			                    return;
			                }                      
			            }
			            //리턴값 설정
			            app.lookup("dsPicList").setValue(instrIdx, "PIC_NO", voReturnVal.getValue("MEMBER_NO")); // 담당자번호
			            app.lookup("dsPicList").setValue(instrIdx, "PIC_NM", voReturnVal.getValue("FLNM")); // 담당자명
			            app.lookup("dsPicList").setValue(instrIdx, "PIC_INST_NO", voReturnVal.getValue("INST_NO")); // 담당기관번호
			            app.lookup("dsPicList").setValue(instrIdx, "PIC_INST_NM", voReturnVal.getValue("INST_NM")); // 담당기관명
			            util.Control.redraw(app, "grdList");            
			        }        
			    });     
			    
			}

