			/*
			 * "중복 확인" 아웃풋(opt28)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onOpt28Click(e){

			    var opt28 = e.control;
			    
			    if(msCrudType != "READ") {
			        
			        var ipb13 = app.lookup("ipb13");
			        var nm = ipb13.value;
			    
			        if (ValueUtil.isNull(nm)) {
			            util.Msg.alert(app, "자원명을 입력해 주십시오.");
			            return false;
			        }
			    
			        var dmChkNm = app.lookup("dmChkNm");
			        dmChkNm.reset();
			    
			        dmChkNm.setValue("nm", nm);
			        
			        app.lookup("subChk").action = '/isry/itgcm/crtrinfo/resrce/selectResrceNmChk.do';        
			    
			        util.Submit.send(app, "subChk", function(){
			            
			            console.log(dmChkNm.getValue("nmExists") );
			    
			            if (dmChkNm.getValue("nmExists") == 1) {
			                util.Msg.confirm(app, "동일한 자원제공서비스명이 존재합니다. 계속 진행하시겠습니까?", null,
			                function() { //진행
			                    bDupChkFlag = true;                 
			                },
			                function() { //취소
			                    ipb13.value = "";
			                    ipb13.focus();
			    
			                    bDupChkFlag = false;
			                    return false;
			    
			                }, "중복확인");
			            } else {
			                util.Msg.alert(app, "사용 가능한 서비스명입니다.");
			                bDupChkFlag = true;
			            }
			        });        
			    }
			}

