			function onCbx3ValueChange(e){
			    var cbx3 = e.control;

			    fn_cbx3ValueChange();
			}

			function fn_cbx3ValueChange() {
			    
			    var cbx3 = app.lookup("cbx3");
			    
			    if (msCrudType == "CREATE") {
			        if (cbx3.value == "Y") {
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_YN", "Y");
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_NO", sinstNo);   // 자원제공주체번호
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_NM", sInstNm);   // 자원제공주체명           
			            app.lookup("sipb_RSFR_INST_NM").visible = false;
			        } else {
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_YN", "N");
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_NO", "");   // 자원제공주체번호
			            app.lookup("dsDetail").setValue(0,"RSFR_INST_NM", "");   // 자원제공주체명           
			            app.lookup("sipb_RSFR_INST_NM").visible = true;           
			        }
			    }
			    util.Control.redraw(app, "grpDefForm");
			}

